from typing import Iterable, List


def is_even(n: int) -> bool:
    return n % 2 == 0


def f(numbers: Iterable[int]) -> List[int]:
    """偶数だけを 2 乗して、元の順序のままリストで返す。"""
    result: List[int] = []
    for n in numbers:
        if is_even(n):
            result.append(n * n)
    return result

def squares_of_evens(numbers):
    """偶数の 2 乗を返す。"""
    return sorted({n * n for n in numbers if n % 2 == 0})


